    for (int k = 0; k < 5; k++) {
        int syncInterval = 460 + k;
        RandomData data1 = new RandomData(SCHEMA, COUNT, SEED);
        RandomData data2 = new RandomData(SCHEMA, COUNT, SEED + 1);
        File file1 = makeFile((codec == null ? "null" : codec.toString()) + "-A");
