    // their underlying representations are primitive types
    assertEquals("java.time.LocalDate", compiler.javaUnbox(dateSchema, false), "Should use LocalDate for date type");
    assertEquals("java.time.LocalTime", compiler.javaUnbox(timeSchema, false), "Should use LocalTime for time-millis type");
    assertEquals("java.time.Instant", compiler.javaUnbox(timestampSchema, false), "Should use DateTime for timestamp-millis type");
}

