@Test
void randomLength() {
    long total = 0;
    int count = 1024 * 1024;
    int min = Short.MAX_VALUE;
    int max = 0;
    Random r = createRandom();
    for (int i = 0; i < count; i++) {
        int length = randomLength(r);
        if (min > length)
            min = length;
        if (max < length)
            max = length;
        total += length;
    }
    assertEquals(0, min);
    assertTrue(max > 1024 * 32);
    float average = total / (float) count;
    assertTrue(average > 16.0f);
    assertTrue(average < 64.0f);
}
